export interface WorkflowRequest {
    /**
     * Ordered list of workflow step definitions.
     * @type {Array<StepDefinition>}
     * @memberof WorkflowRequest
     */
    steps: Array<StepDefinition>;
    /**
     * When `true`, unlocks `write_file`, `scaffold_project`, and `document_ingest` tools for all steps.
     * @type {boolean}
     * @memberof WorkflowRequest
     */
    allowWrite?: boolean;
    /**
     * Force a specific model profile for all steps, bypassing automatic routing.
     * @type {string}
     * @memberof WorkflowRequest
     */
    profile?: WorkflowRequestProfileEnum;
    /**
     * How prior step outputs are carried into subsequent steps. `none` = isolated; `summary` = compact bullet summary (default); `full` = verbatim full output.
     * @type {string}
     * @memberof WorkflowRequest
     */
    carry?: WorkflowRequestCarryEnum;
    /**
     * Per-step agent-loop iteration cap.  Overrides `AGENTS_MAX_STEPS` for this request only.  Defaults to `AGENTS_MAX_STEPS` (env var, default 20).
     * @type {number}
     * @memberof WorkflowRequest
     */
    maxStepsPerStep?: number;
}

